RULES = [
  {"effect": "deny",  "if": lambda s, r, a: s["device"] != "managed"},
  {"effect": "allow", "if": lambda s, r, a: a == "read" and s["team"] == r["owner"]},
  {"effect": "allow", "if": lambda s, r, a: a == "write" and s["team"] == r["owner"] and s["role"] == "admin"},
]
def decide(s, r, a):
    hits = [x["effect"] for x in RULES if x["if"](s, r, a)]
    return "deny" if "deny" in hits else ("allow" if "allow" in hits else "deny(기본)")

r = {"owner": "pay"}
print(decide({"team": "pay", "role": "dev",   "device": "managed"}, r, "read"))    # allow
print(decide({"team": "pay", "role": "dev",   "device": "managed"}, r, "write"))   # deny(기본)
print(decide({"team": "pay", "role": "admin", "device": "personal"}, r, "write"))  # deny
print(decide({"team": "ads", "role": "admin", "device": "managed"}, r, "read"))    # deny(기본)
